int shmid = shmget(key, 4096, IPC_CREAT | 0666); // create a 4KB segment
void *addr = shmat(shmid, NULL, 0);               // attach it into this process

strcpy(addr, "hello from process A");              // ordinary memory write, no system call

// in a completely separate process, attaching the same key
int shmid2 = shmget(key, 4096, 0666);
void *addr2 = shmat(shmid2, NULL, 0);
printf("%s\n", (char *)addr2);                    // reads "hello from process A" directly

